//! Differential parity: `LegacySurrogateV1` must reproduce the frozen
//! Python surrogate (`harness/research_batch.py`) field-for-field on the
//! shared synthetic fixture. The frozen fixture is generated by the Python
//! harness and committed verbatim; if this test fails after a Python-side
//! change, the PYTHON side changed frozen semantics — regenerate the fixture
//! deliberately and document why, never edit expected numbers by hand.

use serde_json::Value;

const EVENTS: &str = include_str!("../../../harness/fixtures/research/synthetic_lifecycle.jsonl");
const FROZEN: &str =
    include_str!("../../../harness/fixtures/research/frozen_batch_synthetic_lifecycle.json");

fn compare(path: &str, rust: &Value, python: &Value) {
    match (rust, python) {
        (Value::Object(r), Value::Object(p)) => {
            let mut keys: Vec<&String> = r.keys().chain(p.keys()).collect();
            keys.sort();
            keys.dedup();
            for key in keys {
                match (r.get(key), p.get(key)) {
                    (Some(rv), Some(pv)) => compare(&format!("{path}.{key}"), rv, pv),
                    (None, Some(_)) => panic!("{path}.{key}: missing in Rust result"),
                    (Some(_), None) => panic!("{path}.{key}: extra in Rust result"),
                    (None, None) => unreachable!(),
                }
            }
        }
        _ => {
            if rust != python {
                panic!("{path}: rust {rust} != python {python}");
            }
        }
    }
}

#[test]
fn legacy_engine_matches_frozen_python_output_exactly() {
    let events = sniper_strategy::load_events(EVENTS).expect("fixture must load");
    let frozen: Value = serde_json::from_str(FROZEN).expect("frozen fixture must parse");
    let python_results = frozen["results"].as_array().expect("results array");

    let results = sniper_strategy::engine::legacy::run_registry(
        &events,
        sniper_strategy::StrategyKnobs::default(),
        100_000_000,
        &sniper_strategy::RiskConstraints::default(),
        &sniper_strategy::engine::legacy::LegacyParams::default(),
    );
    assert_eq!(results.len(), python_results.len());

    for (rust_result, python_result) in results.iter().zip(python_results) {
        let rust_value = serde_json::to_value(rust_result).expect("serialize rust result");
        compare(
            &format!("results[{}]", rust_result.strategy),
            &rust_value,
            python_result,
        );
    }
}

#[test]
fn registry_reruns_are_bit_identical() {
    let events = sniper_strategy::load_events(EVENTS).expect("fixture must load");
    let knobs = sniper_strategy::StrategyKnobs::default();
    let risk = sniper_strategy::RiskConstraints::default();
    let params = sniper_strategy::engine::legacy::LegacyParams::default();
    let a = serde_json::to_string(&sniper_strategy::engine::legacy::run_registry(
        &events,
        knobs,
        100_000_000,
        &risk,
        &params,
    ))
    .unwrap();
    let b = serde_json::to_string(&sniper_strategy::engine::legacy::run_registry(
        &events,
        knobs,
        100_000_000,
        &risk,
        &params,
    ))
    .unwrap();
    assert_eq!(a, b, "registry runs must be bit-identical");
}

#[test]
fn s00_baseline_outperforms_all_traders_on_the_synthetic_cohort() {
    // The honest expected outcome on the frozen synthetic cohort: every
    // trading policy loses money; NO_TRADE (S00, net 0) wins. This pins the
    // dataset's message: surrogate losses are the norm, not a bug.
    let events = sniper_strategy::load_events(EVENTS).expect("fixture must load");
    let results = sniper_strategy::engine::legacy::run_registry(
        &events,
        sniper_strategy::StrategyKnobs::default(),
        100_000_000,
        &sniper_strategy::RiskConstraints::default(),
        &sniper_strategy::engine::legacy::LegacyParams::default(),
    );
    for result in &results[1..] {
        assert!(
            result.net_pnl_lamports < 0,
            "{} should underperform S00 on this cohort (got {})",
            result.strategy,
            result.net_pnl_lamports
        );
    }
    assert_eq!(results[0].net_pnl_lamports, 0);
}
